  for (let i = L.length - 1; i >= 0; i--) { const r = L[i]; if (!r.hand.every(k => SP[k])) { L.splice(i, 1); continue; } r.ups = r.ups.filter(u => { const [k, id] = u.split('.'); return SP[k] && (UPG[k] || []).some(q => q.id === id); }); }
